/**
 * The workspace log's types in JavaScript, generated from their Java
 * declarations.
 *
 * <h2>Generated and hand-written live apart</h2>
 *
 * <p>This module's {@code src/main/resources} is intentionally empty. Its
 * served JS is produced at build time by
 * {@link hue.captains.singapura.js.homing.workspace.codecs.log.WorkspaceLogJsGen}
 * (Maven {@code exec}, {@code process-classes}) into {@code target/classes};
 * generated files are never committed. The manifest,
 * {@link hue.captains.singapura.js.homing.workspace.codecs.log.WorkspaceLogManifest},
 * is the single source of truth: each type the log carries, declared in Java,
 * paired with its own generators.</p>
 *
 * <p>{@link hue.captains.singapura.js.homing.workspace.codecs.WorkspaceLogCodecsModule}
 * is the DomModule that serves the generated JS, its {@code Exportable._Class}
 * records naming what the file exports.</p>
 */
package hue.captains.singapura.js.homing.workspace.codecs;
